function history(){const nav=$('#history');nav.replaceChildren();for(const c of chats){const row=document.createElement('div');row.className='history-row'+(c.id===active?' active':'');const title=button('chat',c.title,()=>{if(busy)return;active=c.id;window.history.pushState(null,'','/'+c.id);render();document.body.classList.remove('sidebar-open')});const titleText=document.createElement('span');titleText.textContent=c.title;title.append(titleText);title.className='history-title';row.append(title);if(c.id===active){for(const [icon,label,fn] of [['edit','Rename conversation',()=>{const n=window.prompt('Conversation name',c.title);if(n?.trim()){c.title=n.trim();save();history()}}],['trash','Delete conversation',()=>{if(busy)return;if(confirm('Delete this conversation?')){chats=chats.filter(x=>x.id!==c.id);active=null;window.history.pushState(null,'','/chat');save();render()}}]]){const b=button(icon,label,fn);b.className='history-action';row.append(b)}}nav.append(row)}}
function inlineMarkdown(target,text){
 const tokens=/(`[^`\n]+`|\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)|\*\*([^*\n]+)\*\*|__([^_\n]+)__|~~([^~\n]+)~~|(?<!\*)\*([^*\n]+)\*(?!\*)|(?<!_)_([^_\n]+)_(?!_))/g;
 let offset=0;
 for(const match of text.matchAll(tokens)){
  target.append(document.createTextNode(text.slice(offset,match.index)));
  let node;
  if(match[1].startsWith('`')){node=document.createElement('code');node.textContent=match[1].slice(1,-1)}
  else if(match[3]){node=document.createElement('a');node.href=match[3];node.target='_blank';node.rel='noreferrer noopener';node.textContent=match[2]}
  else if(match[4]||match[5]){node=document.createElement('strong');node.textContent=match[4]||match[5]}
  else if(match[6]){node=document.createElement('del');node.textContent=match[6]}
  else {node=document.createElement('em');node.textContent=match[7]||match[8]}
  target.append(node);offset=match.index+match[0].length;
 }
 target.append(document.createTextNode(text.slice(offset)));
}
function content(el,text){el.replaceChildren();const pieces=text.split(/(```[\s\S]*?```)/g);for(const piece of pieces){if(piece.startsWith('```')&&piece.endsWith('```')){const pre=document.createElement('pre');const code=document.createElement('code');code.textContent=piece.slice(3,-3).replace(/^\w*\n/,'');pre.append(code);el.append(pre)}else inlineMarkdown(el,piece)}}
function render(){history();$('#selected-model-label').textContent=modelInfo(activeModel()).name;$('#version').textContent='Qwen Classic · '+modelInfo(activeModel()).name;document.querySelector('.columns section:last-child p:last-child').textContent='Early-generation model, with no access to live information';$('#welcome h1').textContent=activeModel()===defaultModel?'Qwen':modelInfo(activeModel()).name;prompt.setAttribute('aria-label','Message '+modelInfo(activeModel()).name);const chat=current();$('#welcome').hidden=!!chat?.messages.length;const messages=$('#messages');messages.replaceChildren();for(const m of chat?.messages||[]){const row=document.createElement('article');row.className='message '+m.role;const inner=document.createElement('div');inner.className='message-inner';const avatar=document.createElement('div');avatar.className=m.role==='assistant'?'assistant-avatar':'user-avatar';if(m.role==='assistant'){avatar.append(modelAvatar(m.model||defaultModel));avatar.title=modelInfo(m.model||defaultModel).name}else avatar.textContent='Y';const text=document.createElement('div');text.className='content'+(m.error?' error-box':'')+(busy&&m===chat.messages.at(-1)&&m.role==='assistant'?' typing':'');content(text,m.content||(busy?'':'Response stopped.'));if(m.role==='assistant')text.dataset.modelLabel=modelInfo(m.model||defaultModel).name;inner.append(avatar,text);if(m.role==='assistant'&&!busy&&!m.error){const actions=document.createElement('div');actions.className='message-tools';actions.append(button('copy','Copy response',async()=>{await navigator.clipboard.writeText(m.content)}));for(const [label,v] of [['up','up'],['down','down']]){const b=button(label,v==='up'?'Good response':'Poor response',()=>{m.rating=m.rating===v?null:v;save();render()});if(m.rating===v)b.className='selected';actions.append(b)}inner.append(actions)}row.append(inner);messages.append(row)}controls();$('#send').disabled=busy||!prompt.value.trim()}
function controls(){const el=$('#generation-controls');el.replaceChildren();if(busy)el.append(textButton('stop','Stop generating',()=>controller.abort()));else if(current()?.messages.some(m=>m.role==='assistant')){const failed=current().messages.at(-1).error;if(failed){const p=document.createElement('p');p.textContent='There was an error generating a response';el.append(p)}const b=textButton('refresh','Regenerate response',()=>generate(true));if(failed)b.className='retry';el.append(b)}}
