$('#about').onclick=$('#version').onclick=()=>navigate('/about');document.querySelectorAll('.example').forEach(b=>b.onclick=()=>{prompt.value=b.textContent.trim().replace(/^“|”$/g,'');prompt.dispatchEvent(new Event('input'));prompt.focus()});async function status(){try{const r=await fetch('/api/status');const d=await r.json();$('#status').style.color=d.ready?'#10a37f':'#d7a644';$('#status').title=d.ready?'Local model runtime ready':'Local model runtime starting'}catch{$('#status').style.color='#ef6060';$('#status').title='Local model is offline'}}render();loadChats();status();setInterval(status,30000);

