$('#status').innerHTML=icon('status');document.querySelectorAll('.column-icon')[0].innerHTML=icon('sun');document.querySelectorAll('.column-icon')[1].innerHTML=icon('bolt');document.querySelectorAll('.example').forEach(b=>{b.textContent=b.textContent.trim();b.insertAdjacentHTML('beforeend',icon('arrow'))});

