const profile=$('.profile'),avatar=profile.querySelector('.user-avatar');function applyProfilePicture(value){avatar.classList.toggle('profile-photo',!!value);avatar.style.backgroundImage=value?`url(${value})`:'';avatar.textContent=value?'':'Y';document.body.classList.toggle('has-profile-picture',!!value);document.documentElement.style.setProperty('--profile-picture',value?`url(${value})`:'none');render()}const savedProfile=localStorage.getItem('qwen-classic-profile-picture');applyProfilePicture(savedProfile);$('#custom-instructions').value=customInstructions;$('#custom-instructions').oninput=e=>{customInstructions=e.target.value.slice(0,4000);localStorage.setItem('qwen-classic-instructions',customInstructions)};profile.tabIndex=0;profile.setAttribute('role','button');profile.setAttribute('aria-label','Open settings');profile.onclick=()=>settings.showModal();profile.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();settings.showModal()}};$('#profile-file').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const image=String(reader.result);localStorage.setItem('qwen-classic-profile-picture',image);applyProfilePicture(image)};reader.readAsDataURL(file)};$('#remove-profile').onclick=()=>{localStorage.removeItem('qwen-classic-profile-picture');applyProfilePicture('')};
